USE scenetrip;

SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE booked_flights;
TRUNCATE TABLE trip_plan_stops;
TRUNCATE TABLE movie_locations;
TRUNCATE TABLE movie_actors;
TRUNCATE TABLE trip_plans;
TRUNCATE TABLE flights;
TRUNCATE TABLE locations;
TRUNCATE TABLE actors;
TRUNCATE TABLE movies;
TRUNCATE TABLE users;
SET FOREIGN_KEY_CHECKS = 1;











-- Row-count checks required by the rubric.
SELECT 'users' AS table_name, COUNT(*) AS row_count FROM users
UNION ALL SELECT 'movies', COUNT(*) FROM movies
UNION ALL SELECT 'locations', COUNT(*) FROM locations
UNION ALL SELECT 'flights', COUNT(*) FROM flights
UNION ALL SELECT 'trip_plans', COUNT(*) FROM trip_plans;
